<script>
	document.addEventListener('DOMContentLoaded', function () {
		document.querySelectorAll('.elementor-menu-toggle').forEach(function (toggle) {
			var dropdown = toggle.nextElementSibling;

			if (!dropdown || !dropdown.classList.contains('elementor-nav-menu--dropdown')) {
				return;
			}

			var setMenuState = function (isOpen) {
				toggle.classList.toggle('elementor-active', isOpen);
				toggle.setAttribute('aria-expanded', String(isOpen));
				dropdown.setAttribute('aria-hidden', String(!isOpen));

				dropdown.querySelectorAll('a').forEach(function (link) {
					link.tabIndex = isOpen ? 0 : -1;
				});
			};

			toggle.addEventListener('click', function (event) {
				event.stopImmediatePropagation();
				setMenuState(toggle.getAttribute('aria-expanded') !== 'true');
			});

			toggle.addEventListener('keydown', function (event) {
				if (event.key === 'Enter' || event.key === ' ') {
					event.preventDefault();
					toggle.click();
				}

				if (event.key === 'Escape') {
					setMenuState(false);
				}
			});

			setMenuState(false);
		});
	});
</script>

